//! The generated files, one `fn(&Table) -> String` each

use crate::table::{Arg, Const, Func, Table, Ty};
use indoc::formatdoc;

const SPDX: &str = "SPDX-License-Identifier: MIT OR GPL-2.0-only";
const NOTE: &str = "GENERATED by tools/ffigen from sdk/mim.ffi: don't edit. Change the table, then run `cargo run -p ffigen`.";

impl Arg {
    /// Its parameters in host_<name>
    fn host_params(&self) -> Vec<String> {
        match self.ty {
            Ty::Bytes => vec![
                format!("const uint8_t *const {}", self.name),
                format!("const uint32_t {}_len", self.name),
            ],
            _ => self
                .values()
                .into_iter()
                .map(|(n, s)| format!("const {} {n}", s.c()))
                .collect(),
        }
    }

    /// What the thunk passes for it
    fn host_call(&self) -> Vec<String> {
        match self.ty {
            Ty::Bytes => vec![
                format!("m.base + {}", self.name),
                format!("{}_len", self.name),
            ],
            _ => vec![self.name.clone()],
        }
    }

    /// Its parameters in the C declaration a guest imports
    fn guest_c_params(&self) -> Vec<String> {
        match self.ty {
            Ty::Scalar(s) => vec![format!("{} {}", s.c(), self.name)],
            // the handler may write through it
            Ty::Ptr => vec![format!("void *{}", self.name)],
            Ty::Bytes => vec![
                format!("const void *{}", self.name),
                format!("uint32_t {}_len", self.name),
            ],
        }
    }

    /// Its parameters in the Rust declaration a guest imports
    fn rust_params(&self) -> Vec<String> {
        match self.ty {
            Ty::Scalar(s) => vec![format!("{}: {}", self.name, s.rust())],
            Ty::Ptr => vec![format!("{}: *mut core::ffi::c_void", self.name)],
            Ty::Bytes => vec![
                format!("{}: *const u8", self.name),
                format!("{}_len: u32", self.name),
            ],
        }
    }
}

fn header() -> String {
    format!("// {SPDX}\n// {NOTE}\n\n")
}

// A declaration: "name(a, b)" on one line, or one per line once there are five or more, as
// clang-format keeps them
fn c_decl(name: &str, params: &[String], end: &str) -> String {
    if params.len() < 5 {
        format!("{name}({}){end}", params.join(", "))
    } else {
        format!("{name}(\n    {}\n){end}", params.join(",\n    "))
    }
}

fn each<T>(items: &[T], line: impl Fn(&T) -> String) -> String {
    items.iter().map(line).collect()
}

// The constants as an anonymous enum, then a blank line; or nothing, since C has no empty enum
fn c_enum(prefix: &str, consts: &[Const]) -> String {
    if consts.is_empty() {
        return String::new();
    }
    let lines = each(consts, |c| {
        format!("    {prefix}{} = {},\n", c.name, c.value)
    });
    format!("enum {{\n{lines}}};\n\n")
}

pub fn host_h(t: &Table) -> String {
    let consts = c_enum("guest_", &t.consts);
    let handlers = each(&t.funcs, |f| {
        if f.direct.is_some() {
            return String::new();
        }
        let params: Vec<String> = std::iter::once("const guest_mem_t *const mem".to_owned())
            .chain(f.args.iter().flat_map(Arg::host_params))
            .chain(f.ret.map(|s| format!("{} *const result", s.c())))
            .collect();
        c_decl(&format!("const char *host_{}", f.name), &params, ";\n")
    });
    header()
        + &formatdoc! {"
            #pragma once

            #include <stdbool.h>
            #include <stddef.h>
            #include <stdint.h>

            #ifdef __cplusplus
            extern \"C\" {{
            #endif

            {consts}// The guest's linear memory, as one import call sees it
            typedef struct guest_mem_t {{
                uint8_t *base;
                size_t size;
            }} guest_mem_t;

            // True if [ptr, ptr + len) is inside the guest's memory; written so ptr + len can't wrap
            static inline bool guest_mem_has(const guest_mem_t *const mem, const uint32_t ptr, const size_t len) {{
                return len <= mem->size && ptr <= mem->size - len;
            }}

            // Written by hand. Each returns NULL, or a message that traps the guest. `bytes` arguments
            // are already checked and arrive as host pointers; `ptr` arguments are guest addresses.
            // An import that returns a value gets `result`, set to 0, to write it into.
            {handlers}
            struct M3Runtime;
            struct M3ImportContext;

            // One import from module \"mim\": its name, its wasm3 signature, and the thunk that calls host_<name>
            typedef struct guest_import_t {{
                const char *name;
                const char *signature;
                const void *(*thunk)(struct M3Runtime *runtime, struct M3ImportContext *ctx, uint64_t *sp, void *mem);
            }} guest_import_t;

            extern const guest_import_t guest_imports[];
            extern const size_t guest_import_count;

            #ifdef __cplusplus
            }}
            #endif
        "}
}

fn thunk(f: &Func) -> String {
    let name = &f.name;
    let ret = f.ret.map_or(String::new(), |s| format!(" -> {}", s.rust()));
    // wasm3 keeps the result's slot first, before the arguments
    let first = usize::from(f.ret.is_some());
    let reads: String = f
        .values()
        .enumerate()
        .map(|(slot, (n, s))| {
            format!(
                "    const {c} {n} = *(const {c} *)&sp[{}];\n",
                slot + first,
                c = s.c()
            )
        })
        .collect();
    let checks: String = f
        .args
        .iter()
        .filter(|a| matches!(a.ty, Ty::Bytes))
        .map(|a| {
            formatdoc! {"
                    if (!guest_mem_has(&m, {n}, {n}_len)) {{
                        return \"mim.{name}: {n} outside guest memory\";
                    }}
                ", n = a.name}
            .lines()
            .map(|l| format!("    {l}\n"))
            .collect::<String>()
        })
        .collect();
    let args: Vec<String> = f.args.iter().flat_map(Arg::host_call).collect();
    let call: Vec<String> = std::iter::once("&m".to_owned())
        .chain(args.iter().cloned())
        .chain(f.ret.map(|_| "&result".to_owned()))
        .collect();
    // a call stays on one line however many arguments it has
    let call = match (&f.direct, f.ret) {
        (Some(d), None) => format!("    {d}({});\n    return NULL;\n", args.join(", ")),
        (Some(d), Some(s)) => format!(
            "    *({c} *)&sp[0] = {d}({});\n    return NULL;\n",
            args.join(", "),
            c = s.c()
        ),
        (None, None) => format!("    return host_{name}({});\n", call.join(", ")),
        (None, Some(s)) => formatdoc! {"
                {c} result = 0;
                const char *const err = host_{name}({call});
                if (err == NULL) {{
                    *({c} *)&sp[0] = result;
                }}
                return err;
            ", c = s.c(), call = call.join(", ")}
        .lines()
        .map(|l| format!("    {l}\n"))
        .collect(),
    };
    // an import with nothing to read or write never touches wasm3's stack
    let unused_sp = if f.values().next().is_none() && f.ret.is_none() {
        "    (void)sp;\n"
    } else {
        ""
    };
    // only handlers and `bytes` checks look at the guest's memory
    let mem = if f.direct.is_none() || f.args.iter().any(|a| matches!(a.ty, Ty::Bytes)) {
        "    const guest_mem_t m = {mem, m3_GetMemorySize(runtime)};\n"
    } else {
        "    (void)runtime;\n    (void)mem;\n"
    };
    let sig = f
        .args
        .iter()
        .map(|a| format!("{}: {}", a.name, a.ty))
        .collect::<Vec<_>>()
        .join(", ");
    formatdoc! {"

        // mim.{name}({sig}){ret}
        static const void *thunk_{name}(IM3Runtime runtime, IM3ImportContext ctx, uint64_t *sp, void *mem) {{
            (void)ctx;
        {unused_sp}{mem}{reads}{checks}{call}}}
    "}
}

pub fn host_c(t: &Table) -> String {
    let thunks = each(&t.funcs, thunk);
    let includes = each(&t.includes, |path| format!("#include \"{path}\"\n"));
    let table = each(&t.funcs, |f| {
        format!(
            "    {{\"{0}\", \"{1}\", thunk_{0}}},\n",
            f.name,
            f.signature()
        )
    });
    header()
        + &formatdoc! {"
            #include \"runtime/guest/ffi.h\"
            {includes}
            #include \"wasm3.h\"

            // Each thunk reads its arguments from wasm3's stack, one 64-bit slot each, checks every
            // `bytes` argument against the guest's memory, then calls the handler, or the host
            // function the table names after `=`.
            {thunks}
            const guest_import_t guest_imports[] = {{
            {table}}};
            const size_t guest_import_count = sizeof(guest_imports) / sizeof(guest_imports[0]);
        "}
}

pub fn rust(t: &Table) -> String {
    let consts = each(&t.consts, |c| {
        format!(
            "pub const {}: usize = {};\n",
            c.name.to_uppercase(),
            c.value
        )
    });
    let decls = each(&t.funcs, |f| {
        let params: Vec<String> = f.args.iter().flat_map(Arg::rust_params).collect();
        let ret = f.ret.map_or(String::new(), |s| format!(" -> {}", s.rust()));
        format!("    pub fn {}({}){ret};\n", f.name, params.join(", "))
    });
    header()
        + &formatdoc! {"
            {consts}
            // wasm32v1-none links without --allow-undefined: imports must name their module
            #[link(wasm_import_module = \"mim\")]
            unsafe extern \"C\" {{
            {decls}}}
        "}
}

pub fn guest_c(t: &Table) -> String {
    let consts = c_enum("mim_", &t.consts);
    let decls = each(&t.funcs, |f| {
        let params: Vec<String> = f.args.iter().flat_map(Arg::guest_c_params).collect();
        let attr = format!(
            "__attribute__((import_module(\"mim\"), import_name(\"{}\")))",
            f.name
        );
        c_decl(
            &format!("{attr} {} mim_{}", f.c_ret(), f.name),
            &params,
            ";\n",
        )
    });
    header()
        + &formatdoc! {"
            // Plain C, so C and C++ guests can both include it

            #pragma once

            #include <stdint.h>

            #ifdef __cplusplus
            extern \"C\" {{
            #endif

            {consts}{decls}
            #ifdef __cplusplus
            }}
            #endif
        "}
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::parse::parse;

    #[test]
    fn edges() {
        // no constants: no enum at all, since C has no empty one
        let t = parse("fn f ()").unwrap();
        assert!(!host_h(&t).contains("enum") && !guest_c(&t).contains("enum"));
        // a result moves the arguments up one slot, and is written only if the handler succeeds
        let t = parse("fn f (a: u32) -> u64").unwrap();
        let c = host_c(&t);
        assert!(
            c.contains("a = *(const uint32_t *)&sp[1]")
                && c.contains("if (err == NULL) {\n        *(uint64_t *)&sp[0] = result;")
        );
        assert!(host_h(&t).contains(
            "host_f(const guest_mem_t *const mem, const uint32_t a, uint64_t *const result)"
        ));
        assert!(
            rust(&t).contains("pub fn f(a: u32) -> u64;")
                && guest_c(&t).contains("uint64_t mim_f(uint32_t a)")
        );
        // an import with no arguments still compiles without warnings
        assert!(host_c(&parse("fn f ()").unwrap()).contains("(void)sp;"));
        assert!(!c.contains("(void)sp;"));
        // `=` calls the host function itself, from ffi.c, which includes its header
        let t = parse(
            "include a/b.h\nfn f (x: f32) = cv_f\nfn g (t: bytes) -> u32 = cv_g\nfn h () = cv_h",
        )
        .unwrap();
        let c = host_c(&t);
        assert!(c.contains("#include \"a/b.h\"\n") && c.contains("    cv_f(x);\n    return NULL;"));
        assert!(c.contains("*(uint32_t *)&sp[0] = cv_g(m.base + t, t_len);\n    return NULL;"));
        // without `bytes` it never looks at memory, and still compiles without warnings
        assert!(
            c.contains("(void)runtime;\n    (void)mem;\n    const float x")
                && c.matches("guest_mem_t m =").count() == 1
        );
        assert!(c.contains("(void)sp;\n    (void)runtime;\n    (void)mem;\n    cv_h();"));
        assert!(!host_h(&t).contains("const char *host_"));
    }
}
